#include "crimsonland_resource.h"

static __forceinline char *decode_destination_bytes_first(
    sfx_entry_t *entry,
    unsigned int remaining)
{
    unsigned int pcm_bytes = entry->pcm_bytes;
    unsigned char *pcm_data = (unsigned char *)entry->pcm_data;
    return (char *)(pcm_bytes - remaining + (unsigned int)pcm_data);
}

static __forceinline char *decode_destination_data_first(
    sfx_entry_t *entry,
    unsigned int remaining)
{
    unsigned char *pcm_data = (unsigned char *)entry->pcm_data;
    unsigned int pcm_bytes = entry->pcm_bytes;
    return (char *)(pcm_data + (pcm_bytes - remaining));
}

static __forceinline char *decode_destination_cursor(
    sfx_entry_t *entry,
    unsigned int remaining)
{
    unsigned char *cursor = (unsigned char *)entry->pcm_data;
    cursor += entry->pcm_bytes - remaining;
    return (char *)cursor;
}
